const {chromium}=require('/Users/evanrobinson/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true});const page=await browser.newPage({viewport:{width:1280,height:720}}),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:8841/',{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>document.querySelector('canvas')?.dataset.care,null,{timeout:90000});await page.waitForTimeout(4000);if(!await page.locator('#advanced-open').isVisible())await page.locator('#settings').click();await page.locator('#advanced-open').click();await page.locator('[data-action=lift]').click();await page.waitForTimeout(1800);const lifted=await page.locator('.motion-status').textContent();const before=await page.locator('canvas').first().getAttribute('data-clock');await page.waitForTimeout(800);const during=await page.locator('canvas').first().getAttribute('data-clock');await page.locator('[data-action=tilt]').click();await page.waitForTimeout(1500);await page.locator('[data-action=return]').click();await page.waitForTimeout(5000);const returned=await page.locator('.motion-status').textContent(),diagnostics=await page.locator('.tile-motion-controls').getAttribute('data-physics');if(await page.locator('[data-action=cancel]').isEnabled())await page.locator('[data-action=cancel]').click();const cancel=await page.locator('.motion-status').textContent();await page.screenshot({path:'tile-physics/browser-desktop.png'});console.log(JSON.stringify({lifted,clockPaused:before===during,returned,diagnostics,cancel,errors}));await browser.close();})().catch(e=>{console.error(e);process.exit(1)});
